Add minimal API endpoints in Program.cs before `app.Run();`:

```csharp
// Shipment API endpoints
app.MapGet("/api/shipments", async (ApplicationDbContext db) =>
{
    var shipments = await db.Shipments
        .OrderByDescending(s => s.ShippedDate)
        .Select(s => new ShipmentDto
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = s.Status,
            ShippedDate = s.ShippedDate,
            EstimatedDelivery = s.EstimatedDelivery,
            ActualDelivery = s.ActualDelivery,
            CustomerEmail = s.CustomerEmail,
            Description = s.Description
        })
        .ToListAsync();
    return Results.Ok(shipments);
}).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));

app.MapPut("/api/shipments/{id}/status", async (int id, StatusUpdateRequest request, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FindAsync(id);
    if (shipment is null) return Results.NotFound();
    shipment.Status = request.Status;
    if (request.Status == "Delivered")
        shipment.ActualDelivery = DateTime.UtcNow;
    await db.SaveChangesAsync();
    return Results.Ok();
}).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));

app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments
        .Where(s => s.TrackingNumber == trackingNumber)
        .Select(s => new ShipmentDto
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = s.Status,
            ShippedDate = s.ShippedDate,
            EstimatedDelivery = s.EstimatedDelivery,
            ActualDelivery = s.ActualDelivery,
            CustomerEmail = s.CustomerEmail,
            Description = s.Description
        })
        .FirstOrDefaultAsync();
    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
});

app.MapGet("/api/shipments/my", async (HttpContext httpContext, ApplicationDbContext db) =>
{
    var email = httpContext.User.Identity?.Name;
    if (string.IsNullOrEmpty(email)) return Results.Unauthorized();
    var shipments = await db.Shipments
        .Where(s => s.CustomerEmail == email)
        .OrderByDescending(s => s.ShippedDate)
