    private List<ShipmentDto> shipments = new();
    private string searchTerm = string.Empty;
    private string statusFilter = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private IEnumerable<ShipmentDto> FilteredShipments => shipments.Where(s =>
        (string.IsNullOrEmpty(statusFilter) || s.Status == statusFilter) &&
        (string.IsNullOrEmpty(searchTerm) ||
         s.TrackingNumber.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
         s.Destination.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)));

    protected override async Task OnInitializedAsync() => await LoadShipments();

    private async Task LoadShipments()
    {
        isLoading = true;
        errorMessage = null;
        try
        {
            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments") ?? new();
        }
        catch
        {
            errorMessage = "Failed to load shipments.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, string newStatus)
    {
        try
        {
            var response = await Http.PutAsJsonAsync($"api/shipments/{shipment.Id}/status",
                new { Status = newStatus });
            if (response.IsSuccessStatusCode)
            {
                shipment.Status = newStatus;
                if (newStatus == "Delivered")
                    shipment.ActualDelivery = DateTime.UtcNow;
            }
        }
        catch
        {
            errorMessage = "Failed to update status.";
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Out for Delivery" => "bg-info text-dark",
        "Delayed" => "bg-danger",
        "Pending" => "bg-secondary",
        _ => "bg-dark"
    };
}
