+@page "/"
+@rendermode InteractiveAuto
+@using ShipmentTracker.Client.Models
+@inject HttpClient Http
+
+<PageTitle>Track Shipment</PageTitle>
+
+<h1>📦 Shipment Tracker</h1>
+<p class="lead">Enter your tracking number to check shipment status.</p>
+
+<div class="row mb-4">
+    <div class="col-md-6">
+        <div class="input-group">
+            <input type="text" class="form-control" placeholder="e.g. TRK-10001"
+                   @bind="trackingNumber" @bind:event="oninput"
+                   @onkeydown="HandleKeyDown" />
+            <button class="btn btn-primary" @onclick="TrackShipmentAsync" disabled="@isLoading">
+                @if (isLoading) { <span class="spinner-border spinner-border-sm me-1"></span> }
+                Track
+            </button>
+        </div>
+    </div>
+</div>
+
+@if (errorMessage is not null)
+{
+    <div class="alert alert-warning">@errorMessage</div>
+}
+
+@if (shipment is not null)
+{
+    <div class="card">
+        <div class="card-header d-flex justify-content-between align-items-center">
+            <strong>@shipment.TrackingNumber</strong>
+            <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
+        </div>
+        <div class="card-body">
+            <div class="row">
+                <div class="col-md-6">
+                    <p><strong>Description:</strong> @shipment.Description</p>
+                    <p><strong>Origin:</strong> @shipment.Origin</p>
+                    <p><strong>Destination:</strong> @shipment.Destination</p>
+                </div>
+                <div class="col-md-6">
+                    <p><strong>Shipped:</strong> @shipment.ShippedDate.ToString("MMM dd, yyyy")</p>
+                    <p><strong>Estimated Delivery:</strong> @(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</p>
+                    @if (shipment.ActualDelivery.HasValue)
+                    {
+                        <p><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</p>
+                    }
+                </div>
+            </div>
+        </div>
+    </div>
+}
+
+@code {
+    private string trackingNumber = string.Empty;
+    private ShipmentDto? shipment;
+    private string? errorMessage;
+    private bool isLoading;
+
+    private async Task HandleKeyDown(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter") await TrackShipmentAsync();
+    }
+
+    private async Task TrackShipmentAsync()
+    {
+        errorMessage = null;
+        shipment = null;
+
+        if (string.IsNullOrWhiteSpace(trackingNumber))
+        {
+            errorMessage = "Please enter a tracking number.";
+            return;
+        }
+
+        isLoading = true;
+        try
+        {
+            var response = await Http.GetAsync($"api/shipments/track/{Uri.EscapeDataString(trackingNumber.Trim())}");
+            if (response.IsSuccessStatusCode)
+            {
+                shipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
+            }
+            else
+            {
+                errorMessage = "Shipment not found. Please check the tracking number.";
+            }
+        }
+        catch
+        {
+            errorMessage = "Unable to reach the server. Please try again.";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private static string GetStatusBadgeClass(string status) => status switch
+    {
+        "Delivered" => "bg-success",
+        "In Transit" => "bg-primary",
+        "Out for Delivery" => "bg-info text-dark",
+        "Delayed" => "bg-danger",
+        "Pending" => "bg-secondary",
+        _ => "bg-dark"
+    };
+}
+

