+@page "/my-shipments"
+@rendermode InteractiveAuto
+@using Microsoft.AspNetCore.Authorization
+@using ShipmentTracker.Client.Models
+@attribute [Authorize(Roles = "Customer")]
+@inject HttpClient Http
+
+<PageTitle>My Shipments</PageTitle>
+
+<h1>📋 My Shipments</h1>
+
+<div class="row mb-3">
+    <div class="col-md-3">
+        <select class="form-select" @bind="statusFilter">
+            <option value="">All Statuses</option>
+            <option value="Pending">Pending</option>
+            <option value="In Transit">In Transit</option>
+            <option value="Out for Delivery">Out for Delivery</option>
+            <option value="Delivered">Delivered</option>
+            <option value="Delayed">Delayed</option>
+        </select>
+    </div>
+    <div class="col-md-2">
+        <button class="btn btn-outline-secondary" @onclick="LoadShipments">↻ Refresh</button>
+    </div>
+</div>
+
+@if (isLoading)
+{
+    <p><em>Loading your shipments...</em></p>
+}
+else if (errorMessage is not null)
+{
+    <div class="alert alert-danger">@errorMessage</div>
+}
+else if (!shipments.Any())
+{
+    <div class="alert alert-info">You have no shipments yet.</div>
+}
+else
+{
+    @foreach (var s in FilteredShipments)
+    {
+        <div class="card mb-3">
+            <div class="card-header d-flex justify-content-between align-items-center">
+                <strong>@s.TrackingNumber</strong>
+                <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
+            </div>
+            <div class="card-body">
+                <div class="row">
+                    <div class="col-md-6">
+                        <p><strong>Description:</strong> @s.Description</p>
+                        <p><strong>From:</strong> @s.Origin</p>
+                        <p><strong>To:</strong> @s.Destination</p>
+                    </div>
+                    <div class="col-md-6">
+                        <p><strong>Shipped:</strong> @s.ShippedDate.ToString("MMM dd, yyyy")</p>
+                        <p>
+                            <strong>Estimated Delivery:</strong>
+                            @if (s.EstimatedDelivery.HasValue)
+                            {
+                                @s.EstimatedDelivery.Value.ToString("MMM dd, yyyy")
+                                var daysLeft = (s.EstimatedDelivery.Value.Date - DateTime.UtcNow.Date).Days;
+                                if (s.Status != "Delivered")
+                                {
+                                    if (daysLeft > 0)
+                                    {
+                                        <span class="text-muted">(@daysLeft day(s) away)</span>
+                                    }
+                                    else if (daysLeft == 0)
+                                    {
+                                        <span class="text-success">(Today!)</span>
+                                    }
+                                    else
+                                    {
+                                        <span class="text-danger">(@Math.Abs(daysLeft) day(s) overdue)</span>
+                                    }
+                                }
+                            }
+                            else
+                            {
+                                <text>—</text>
+                            }
+                        </p>
+                        @if (s.ActualDelivery.HasValue)
+                        {
+                            <p><strong>Delivered On:</strong> @s.ActualDelivery.Value.ToString("MMM dd, yyyy") ✓</p>
+                        }
+                    </div>
+                </div>
+            </div>
+        </div>
+    }
+
+    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
+}
+
+@code {
+    private List<ShipmentDto> shipments = new();
+    private string statusFilter = string.Empty;
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    private IEnumerable<ShipmentDto> FilteredShipments => shipments.Where(s =>
+        string.IsNullOrEmpty(statusFilter) || s.Status == statusFilter);
+
+    protected override async Task OnInitializedAsync() => await LoadShipments();
+
+    private async Task LoadShipments()
+    {
+        isLoading = true;
+        errorMessage = null;
+        try
+        {
+            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments/my") ?? new();
+        }
+        catch
+        {
+            errorMessage = "Failed to load your shipments.";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private static string GetStatusBadgeClass(string status) => status switch
+    {
+        "Delivered" => "bg-success",
+        "In Transit" => "bg-primary",
+        "Out for Delivery" => "bg-info text-dark",
+        "Delayed" => "bg-danger",
+        "Pending" => "bg-secondary",
+        _ => "bg-dark"
+    };
+}
+

